#!/usr/bin/env python3
"""Collect metrics generated by the final consolidated RUL modeling campaign."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Dict, List

import pandas as pd


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description="Collect final campaign metrics from all shards.")
    p.add_argument("--campaign-root", type=Path, default=Path("~/outputs/batteries_modeling_v3/modeling_results_final_campaign_v1").expanduser())
    p.add_argument("--output-dir", type=Path, default=None)
    return p.parse_args()


def infer_from_path(path: Path, campaign_root: Path) -> Dict[str, object]:
    try:
        rel = path.relative_to(campaign_root)
    except ValueError:
        rel = path
    parts = rel.parts
    info: Dict[str, object] = {"source_file": str(rel)}

    # Expected path: shards/<component>/seed_<seed>/<phase>_<mode>/...
    if len(parts) >= 4 and parts[0] == "shards":
        info["path_component"] = parts[1]
        seed_match = re.match(r"seed_(\d+)", parts[2])
        if seed_match:
            info["path_seed"] = int(seed_match.group(1))
        shard = parts[3]
        info["path_shard"] = shard
        for phase in ["charge", "discharge"]:
            if shard.startswith(phase + "_"):
                info["path_phase"] = phase
                info["path_mode"] = shard[len(phase) + 1:]
                break
    return info


def read_csvs(paths: List[Path], campaign_root: Path) -> pd.DataFrame:
    frames = []
    for path in sorted(paths):
        try:
            df = pd.read_csv(path)
        except Exception as exc:
            print(f"[WARN] Could not read {path}: {exc}")
            continue
        if df.empty:
            continue
        info = infer_from_path(path, campaign_root)
        for k, v in info.items():
            if k not in df.columns:
                df[k] = v
        frames.append(df)
    if not frames:
        return pd.DataFrame()
    return pd.concat(frames, ignore_index=True)


def save(df: pd.DataFrame, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    df.to_csv(path, index=False)
    print(f"[WRITE] {path} rows={len(df)} cols={len(df.columns)}")


def main() -> None:
    args = parse_args()
    campaign_root = args.campaign_root.expanduser()
    output_dir = (args.output_dir or (campaign_root / "summary")).expanduser()
    output_dir.mkdir(parents=True, exist_ok=True)

    print(f"[INFO] Campaign root: {campaign_root}")
    print(f"[INFO] Output dir:    {output_dir}")

    specs = {
        "global": "all_metrics_global.csv",
        "dataset": "all_metrics_dataset.csv",
        "battery": "all_metrics_battery.csv",
        "rul_bin": "all_metrics_rul_bin.csv",
        "macro_by_dataset": "all_metrics_macro_by_dataset.csv",
    }

    summary = {}
    for name, filename in specs.items():
        paths = list((campaign_root / "shards").rglob(filename))
        df = read_csvs(paths, campaign_root)
        out = output_dir / f"final_campaign_metrics_{name}.csv"
        save(df, out)
        summary[name] = {"files": len(paths), "rows": int(len(df)), "columns": list(df.columns)}

    cv_paths = list((campaign_root / "shards").rglob("cv_metrics.csv"))
    cv_df = read_csvs(cv_paths, campaign_root)
    save(cv_df, output_dir / "final_campaign_cv_metrics.csv")
    summary["cv_metrics"] = {"files": len(cv_paths), "rows": int(len(cv_df)), "columns": list(cv_df.columns)}

    global_path = output_dir / "final_campaign_metrics_global.csv"
    if global_path.exists():
        g = pd.read_csv(global_path)
        if not g.empty:
            group_cols = [c for c in ["campaign_component", "random_state", "phase", "mode", "experiment", "model"] if c in g.columns]
            metric_cols = [c for c in ["MAE", "RMSE", "R2", "sMAPE", "nMAE", "nRMSE"] if c in g.columns]
            if group_cols and metric_cols:
                stability = (
                    g.groupby(group_cols, dropna=False)[metric_cols]
                    .agg(["mean", "std", "min", "max", "count"])
                )
                stability.columns = ["_".join(map(str, col)).strip("_") for col in stability.columns.to_flat_index()]
                stability = stability.reset_index()
                save(stability, output_dir / "final_campaign_metric_stability_by_component.csv")

            # Repeated split stability across seeds for global/per_dataset only.
            seed_cols = [c for c in ["phase", "mode", "scope", "experiment", "model"] if c in g.columns]
            if "random_state" in g.columns and seed_cols and metric_cols:
                subset = g[g["mode"].isin(["global", "per_dataset"])] if "mode" in g.columns else g
                repeated = (
                    subset.groupby(seed_cols, dropna=False)[metric_cols]
                    .agg(["mean", "std", "min", "max", "count"])
                )
                repeated.columns = ["seed_" + "_".join(map(str, col)).strip("_") for col in repeated.columns.to_flat_index()]
                repeated = repeated.reset_index()
                save(repeated, output_dir / "final_campaign_repeated_seed_stability.csv")

            # Best global/per-dataset/lodo summaries.
            sort_cols = [c for c in ["phase", "mode", "scope", "experiment"] if c in g.columns]
            if sort_cols and "MAE" in g.columns:
                idx = g.groupby(sort_cols, dropna=False)["MAE"].idxmin()
                best = g.loc[idx].sort_values(sort_cols).reset_index(drop=True)
                save(best, output_dir / "final_campaign_best_by_case.csv")

    with open(output_dir / "final_campaign_collection_summary.json", "w", encoding="utf-8") as f:
        json.dump(summary, f, indent=2, ensure_ascii=False)
    print(f"[DONE] Summary written to {output_dir / 'final_campaign_collection_summary.json'}")


if __name__ == "__main__":
    main()
